    tiles.set_current_tilemap(tilemap("""
        level3 
        """)) #both the background colour changes to white, and a tilemap template becomes the new game setting.
    music.stop_all_sounds() #here i am ordering any existing background music to end
    music.play(music.create_song(hex("""
            
            """)), #and looping a new song, furhter emphasising the scene change.
        music.PlaybackMode.LOOPING_IN_BACKGROUND) #here i specify i want this music to keep looping in the background rather then play for a specified amount of time or until end
