def on_on_overlap2(sprite, otherSprite): #instead, it provides and extra cutscene where students discuss using AI to complete homework
    story.sprite_say_text(npc1, "Did you do that worksheet we got given?")
    story.sprite_say_text(npc2,
        "Yeah, just put it into chat and it gave me the answers, here!")
    sprites.destroy(npc1)
    sprites.destroy(npc2) #if this event occurs, both sprites are deleted after the conversation
    story.sprite_say_text(mySprite,
        "Well..I don't think that counts as actually doing work") #and the playable character then expresses their own thoughts on the matter
sprites.on_overlap(SpriteKind.player, SpriteKind.npc, on_on_overlap2)

def on_on_overlap3(sprite2, otherSprite2):
    info.change_score_by(1)
    effects.confetti.start_screen_effect(1000)
    music.play(music.melody_playable(music.ba_ding),
        music.PlaybackMode.UNTIL_DONE)
    story.sprite_say_text(mySprite, "Pythagoras Theorem.. sounds confusing")
    sprites.destroy(bookmath2)
sprites.on_overlap(SpriteKind.player, SpriteKind.bookmath, on_on_overlap3)

def on_on_overlap4(sprite22, otherSprite22): #this here is where, if the player runs into the car in the opening scene, the game ends and restarts, with a warning message
    music.stop_all_sounds() #all background sound ends
    game.game_over(False) #here the game is marked as over, but not as a win, win would be TRUE, this is marked FALSE, a use of boolean operators
    game.set_game_over_message(False, "GAME OVER! BE CAREFUL!")
sprites.on_overlap(SpriteKind.player, SpriteKind.enemy, on_on_overlap4)

def on_on_score(): #This here is what will happen once the score counter reaches 7, as specified in the closing line of the function
    global textSprite2
    music.stop_all_sounds()
    scene.set_background_color(1) #another scene change, now to a blank white background and tilemap
    tiles.set_current_tilemap(tilemap("""
        level4
        """))
    sprites.destroy(mySprite)
    textSprite2 = textsprite.create(":")
    
    def on_start_cutscene(): #with a cutscene used as an end credits segment on the overall message of the story, and thanks
        story.set_sound_enabled(True)
        story.sprite_say_text(textSprite2,
            "AI is quickly taking over schools and workplaces")
        story.sprite_say_text(textSprite2,
            "However, it is most often used as a way to cognitively off load")
        story.sprite_say_text(textSprite2,
            "Putting convenience before the things that make us human")
        story.sprite_say_text(textSprite2, "That keep our brains healthy")
        story.sprite_say_text(textSprite2,
            "And in doing so, we are also harming our planet")
        story.sprite_say_text(textSprite2, "AI is everywhere, can be used for everything")
        story.sprite_say_text(textSprite2,
            "But AI is no one, it is a mixture of everyone and it doesn't not represent you")
        story.sprite_say_text(textSprite2,
            "This game was a project driven by passion, made by hand")
        story.sprite_say_text(textSprite2,
            "It involved learning along the way and makes it a human experience")
        story.sprite_say_text(textSprite2, "So next time you have to create something")
        story.sprite_say_text(textSprite2,
            "See how you go on your own, you may surprise yourself")
        story.sprite_say_text(textSprite2, "because the human brain can be so powerful.")
        story.sprite_say_text(textSprite2, "thanks for playing!")
    story.start_cutscene(on_start_cutscene)
    
info.on_score(7, on_on_score) #this groups in the above occurance to happen once the score reaches 7

